INSERT INTO paginas (slug, titulo, conteudo) VALUES ('politica-de-privacidade', 'Política de Privacidade', '<h3>Quais dados coletamos</h3><p>Para vender e entregar suas velas, pedimos: nome, e-mail, telefone, CPF e endereço de entrega. O pagamento é processado por um provedor de pagamento (você é levado à página dele); nós não vemos nem guardamos dados do seu cartão.</p>
INSERT INTO paginas (slug, titulo, conteudo) VALUES ('prazos-e-envio', 'Prazos e Envio', '<h3>Separação e envio</h3><p>Depois que o pagamento é confirmado, separamos o seu pedido e o enviamos {{envio}}. Você recebe um e-mail quando ele for postado, com o código de rastreio.</p>
INSERT INTO paginas (slug, titulo, conteudo) VALUES ('trocas-e-devolucoes', 'Trocas e Devoluções', '<h3>Desistência da compra (arrependimento)</h3><p>Como a compra é feita pela internet, você pode desistir em até <strong>7 dias corridos</strong> a contar do recebimento, conforme o art. 49 do Código de Defesa do Consumidor. O produto deve ser devolvido sem uso e na embalagem. Devolvemos o valor pago, inclusive o frete, pelo mesmo meio de pagamento.</p>
